DELETE FROM user_sessions WHERE user_id IN (SELECT id FROM users WHERE username LIKE 'demo.%');
DELETE FROM tenant_memberships WHERE tenant_id = '9f1c2d3e-4b5a-4c6d-8e7f-0a1b2c3d4e5f' OR user_id IN (SELECT id FROM (SELECT id FROM users WHERE username LIKE 'demo.%') x);
DELETE FROM users WHERE username LIKE 'demo.%';
DELETE FROM persons WHERE tenant_id = '9f1c2d3e-4b5a-4c6d-8e7f-0a1b2c3d4e5f';
DELETE FROM branches WHERE tenant_id = '9f1c2d3e-4b5a-4c6d-8e7f-0a1b2c3d4e5f';
DELETE FROM tenants WHERE id = '9f1c2d3e-4b5a-4c6d-8e7f-0a1b2c3d4e5f';

