-- ── Proveedor habitual (el de la última compra) y cliente con lista propia ──
UPDATE `products` p
JOIN (
  SELECT ranked.product_id, ranked.supplier_person_id
  FROM (
    SELECT i.product_id, r.supplier_person_id,
           ROW_NUMBER() OVER (PARTITION BY i.product_id ORDER BY r.created_at DESC, r.id DESC) AS rn
    FROM `purchase_receipt_items` i
    JOIN `purchase_receipts` r ON r.id = i.purchase_receipt_id
    WHERE r.tenant_id = '9f1c2d3e-4b5a-4c6d-8e7f-0a1b2c3d4e5f'
  ) ranked
  WHERE ranked.rn = 1
) last_supplier ON last_supplier.product_id = p.id
SET p.supplier_person_id = last_supplier.supplier_person_id
WHERE p.tenant_id = '9f1c2d3e-4b5a-4c6d-8e7f-0a1b2c3d4e5f' AND p.supplier_person_id IS NULL;
UPDATE `document_sequences` SET `value` = 37 WHERE `tenant_id` = '9f1c2d3e-4b5a-4c6d-8e7f-0a1b2c3d4e5f' AND `name` = 'PERSON_ACCOUNT';

-- Caja donde se cobró cada venta (para el cierre X/Z): la del cobro en efectivo.
UPDATE `sales` s
JOIN (
  SELECT p.sale_id, MIN(m.cash_session_id) AS cash_session_id
  FROM `cash_movements` m
  JOIN `sale_payments` p ON p.id = m.source_id AND m.source_type = 'SALE_PAYMENT'
  WHERE m.tenant_id = '9f1c2d3e-4b5a-4c6d-8e7f-0a1b2c3d4e5f'
  GROUP BY p.sale_id
) linked ON linked.sale_id = s.id
SET s.cash_session_id = linked.cash_session_id
WHERE s.tenant_id = '9f1c2d3e-4b5a-4c6d-8e7f-0a1b2c3d4e5f' AND s.cash_session_id IS NULL;

-- Tarjetas y cuotas que se ofrecen al cobrar (el plan de 12 cuotas vale solo los jueves).

COMMIT;

-- Resumen de lo cargado
SELECT 'Empresa' AS dato, legal_name AS valor FROM tenants WHERE id = '9f1c2d3e-4b5a-4c6d-8e7f-0a1b2c3d4e5f'
UNION ALL SELECT 'Sucursales', COUNT(*) FROM branches WHERE tenant_id = '9f1c2d3e-4b5a-4c6d-8e7f-0a1b2c3d4e5f'
UNION ALL SELECT 'Productos', COUNT(*) FROM products WHERE tenant_id = '9f1c2d3e-4b5a-4c6d-8e7f-0a1b2c3d4e5f'
UNION ALL SELECT 'Clientes y proveedores', COUNT(*) FROM persons WHERE tenant_id = '9f1c2d3e-4b5a-4c6d-8e7f-0a1b2c3d4e5f'
UNION ALL SELECT 'Ventas', COUNT(*) FROM sales WHERE tenant_id = '9f1c2d3e-4b5a-4c6d-8e7f-0a1b2c3d4e5f'
UNION ALL SELECT 'Pedidos esperando cobro', COUNT(*) FROM sales_orders WHERE tenant_id = '9f1c2d3e-4b5a-4c6d-8e7f-0a1b2c3d4e5f' AND status = 'PENDING'
UNION ALL SELECT 'Facturación total', CONCAT('$ ', FORMAT(SUM(total), 2, 'es_AR')) FROM sales WHERE tenant_id = '9f1c2d3e-4b5a-4c6d-8e7f-0a1b2c3d4e5f'
UNION ALL SELECT 'Usuarios demo', GROUP_CONCAT(username) FROM users WHERE username LIKE 'demo.%';

